(function(idleService,fs,basePath,ignoreError,audioAlreadyActive){let frameTimer=0,audioWatchTimer=0,logoImage,bombImage,bombX,bombY,logoFramesRemaining=60,bombReady=0,movementPhase=0,ownsAudio=0;function resetBomb(index){switch(index){case 0:bombX[index]=455;bombY[index]=-67;break;case 1:bombX[index]=520;bombY[index]=-125;break;case 2:bombX[index]=585;bombY[index]=-85;break;case 3:bombX[index]=650;bombY[index]=-155;break;case 4:bombX[index]=715;bombY[index]=-215;break;case 5:bombX[index]=780;bombY[index]=-115;break;case 6:bombX[index]=845;bombY[index]=-185;break;case 7:bombX[index]=910;bombY[index]=-255;break;case 8:bombX[index]=360;bombY[index]=-300;break;case 9:bombX[index]=430;bombY[index]=-240;break;case 10:bombX[index]=500;bombY[index]=-330;break;case 11:bombX[index]=570;bombY[index]=-270;break;case 12:bombX[index]=640;bombY[index]=-360;break;default:bombX[index]=710;bombY[index]=-210;}}function restartOwnedAudio(){if(idleService.active&&ownsAudio&&Pip.audioIsPlaying&&!Pip.audioIsPlaying()){try{Pip.audioStart(basePath+"FALLOUT.WAV",{repeat:true});}catch(error){ignoreError("screensaver audio restart failed:"+error);}}}function startBombRenderer(){if(bombReady)return 1;logoImage=undefined;process.memory(true);E.defrag();try{bombImage={width:71,height:67,bpp:2,transparent:0,buffer:fs.readFileSync(basePath+"BOMB.BIN")};}catch(error){ignoreError("BOMB.BIN load failed:"+error);return 0;}bombX=new Int16Array([455,390,325,255,185,520,445,370,295,610,535,460,385,690]);bombY=new Int16Array([-67,-22,18,62,106,-125,-170,-215,-260,-70,-120,-170,-220,-130]);bombReady=1;if(!audioAlreadyActive){try{Pip.audioStart(basePath+"FALLOUT.WAV",{repeat:true});ownsAudio=1;}catch(error){ignoreError("screensaver audio start failed:"+error);}if(ownsAudio)audioWatchTimer=setInterval(restartOwnedAudio,10000);}return 1;}function drawFrame(){"ram";let bombIndex;if(!idleService.active)return;h.reset().setClipRect(0,0,479,319).clear(0);if(logoFramesRemaining>0){h.setColor(3).drawImage(logoImage,(480 - logoImage.width)>>1,(320 - logoImage.height)>>1);logoFramesRemaining--;h.flip();Pip.lastFlip=getTime();return;}if(!bombReady&&!startBombRenderer()){idleService.stop(1);return;}for(bombIndex=0;bombIndex<14;bombIndex++){h.drawImage(bombImage,bombX[bombIndex],bombY[bombIndex]);bombX[bombIndex]-=movementPhase?3:2;bombY[bombIndex]+=2;if(bombIndex===1||bombIndex===5||bombIndex===10){bombX[bombIndex]--;bombY[bombIndex]++;}if(bombX[bombIndex]<-71&&bombY[bombIndex]>320)resetBomb(bombIndex);}movementPhase=movementPhase?0:1;h.flip();Pip.lastFlip=getTime();}function stopRenderer(){if(frameTimer){clearInterval(frameTimer);frameTimer=0;}if(audioWatchTimer){clearInterval(audioWatchTimer);audioWatchTimer=0;}if(ownsAudio){try{Pip.audioStop();}catch(error){ignoreError("screensaver audio stop failed:"+error);}}ownsAudio=0;logoImage=bombImage=bombX=bombY=undefined;h.reset().setClipRect(0,0,479,319);process.memory(true);E.defrag();}try{logoImage={width:240,height:227,bpp:1,transparent:0,buffer:fs.readFileSync(basePath+"LOGO.BIN")};}catch(error){ignoreError("LOGO.BIN load failed:"+error);return;}h.reset().setClipRect(0,0,479,319).clear(0);h.flip();Pip.lastFlip=getTime();drawFrame();frameTimer=setInterval(drawFrame,83);return{stop:stopRenderer};});
